def _lines(lines: List[str]) -> str:
    return "".join(line + "\n" for line in lines)


def _cmd_balance(args) -> str:
    total = format_amount(reports.balance(_read_ledger(args.file)))
    if args.json:
        return json.dumps({"balance": total}) + "\n"
    return total + "\n"


def _cmd_summary(args) -> str:
    entries = _read_ledger(args.file)
    totals = reports.by_month(entries) if args.by == "month" else reports.by_category(entries)
    formatted = {name: format_amount(totals[name]) for name in sorted(totals)}
    if args.json:
        return json.dumps(formatted) + "\n"
    return _lines(["%s  %s" % item for item in formatted.items()])


def _cmd_list(args) -> str:
    entries = _read_ledger(args.file)
    entries = _sorted_entries(
        reports.filter_entries(entries, args.category, args.since, args.until)
    )
    if args.json:
        return json.dumps([_entry_json(e) for e in entries]) + "\n"
    return _lines([format_entry(e) for e in entries])


def _cmd_export(args) -> str:
    entries = _sorted_entries(_read_ledger(args.file))
    buffer = io.StringIO()
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in entries:
        row = _entry_json(e)
        writer.writerow([row["date"], row["category"], row["amount"], row["note"]])
    return buffer.getvalue()


def _cmd_add(args) -> str:
    for label, value in (("date", args.date), ("category", args.category), ("amount", args.amount)):
        if not value or any(ch.isspace() for ch in value):
            raise _Failure(1, "line 1: invalid %s %r" % (label, value))
    if "\n" in args.note or "\r" in args.note:
        raise _Failure(1, "line 1: note must not contain a newline")
    try:
        parsed = parse("%s %s %s %s" % (args.date, args.category, args.amount, args.note))
    except ParseError as exc:
        raise _Failure(1, str(exc))
    line = format_entry(parsed[0])

    try:
        prefix = ""
        try:
            with open(args.file, "rb") as handle:
                handle.seek(0, 2)
                if handle.tell() > 0:
                    handle.seek(-1, 2)
                    if handle.read(1) != b"\n":
                        prefix = "\n"
        except FileNotFoundError:
            pass
        with open(args.file, "ab") as handle:
            handle.write((prefix + line + "\n").encode("utf-8"))
    except OSError as exc:
        raise _Failure(2, "cannot write %s: %s" % (args.file, exc.strerror or exc))
    return line + "\n"


