def _silence_stdout() -> None:
    """Point stdout at devnull so the flush at interpreter exit cannot fail again."""
    try:
        fd = sys.stdout.fileno()
        devnull = os.open(os.devnull, os.O_WRONLY)
        try:
            os.dup2(devnull, fd)
        finally:
            os.close(devnull)
    except (OSError, ValueError, AttributeError):
        pass  # stdout has no real file descriptor (e.g. replaced in a test)


def _write_stdout(output: str) -> int:
    """Write and flush ``output``; a closed reader ends quietly, other errors exit 2."""
    try:
        sys.stdout.write(output)
        sys.stdout.flush()
    except OSError as exc:
        _silence_stdout()
        if isinstance(exc, BrokenPipeError) or exc.errno == errno.EPIPE:
            return 0
        sys.stderr.write("pennywise: cannot write output: %s\n" % (exc.strerror or exc))
        return 2
    return 0


